  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction transformed electron microscopy from an important technique into a direct sub-angstrom tool for seeing and measuring matter atom by atom.",
        "attribution": "Rose supplied the decisive corrector concepts, while Haider and Urban were central to their practical realization and establishment in materials research.",
        "maturity": "The improvement is repeatedly and independently demonstrated, widely deployed, and has reshaped experimental materials physics over decades.",
        "uncertainties": [
          "The historical boundary between conceptual electron-optics contributions and engineering realization needs careful archival attribution."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B032",
      "proposed_laureates": [
        "James G. Fujimoto",
        "Eric A. Swanson",
        "David Huang"
      ],
      "assessment": {
        "nobel_worthiness": "Optical coherence tomography is an exceptionally clear invention: it opened noninvasive depth-resolved imaging and has directly benefited medicine on a vast scale.",
        "attribution": "Fujimoto, Swanson, and Huang represent the foundational invention and first demonstration rather than later clinical refinement.",
        "maturity": "Its physical principle, technical reproducibility, and clinical importance have been established for many years.",
        "uncertainties": [
          "The precise allocation of credit among the original team and related early low-coherence interferometry work requires record-based review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers and Kerr-lens mode locking furnished a broadly enabling route to few-cycle ultrafast pulses, underpinning major advances including attosecond science.",
        "attribution": "Moulton's titanium-sapphire laser development and Sibbett's pivotal Kerr-lens mode-locking work identify a compact original-credit case.",
        "maturity": "The technology is mature, reproducible, and its scientific consequences are extensive and durable.",
        "uncertainties": [
          "The degree to which the prize topic should separate the gain-medium invention from the mode-locking mechanism needs delimitation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Shinji Yuasa",
        "William H. Butler",
        "Stuart S. P. Parkin"
      ],
      "assessment": {
        "nobel_worthiness": "Crystalline MgO tunnel junctions made giant tunnelling magnetoresistance a powerful, practical spintronic effect and linked a microscopic prediction to transformative device performance.",
        "attribution": "Butler's symmetry-filtering theory and Yuasa's experimental demonstration are especially direct; Parkin's role in establishing the effect and its technological relevance merits close consideration.",
        "maturity": "The phenomenon is experimentally secure and central to mature magnetic-memory technology.",
        "uncertainties": [
          "Independent and near-contemporaneous experimental demonstrations make priority and the appropriate three-person attribution sensitive."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B058",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks created a qualitatively new standard of time and frequency measurement with exceptional precision and wide scientific reach.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept and realization; Ye made foundational experimental advances that established the field.",
        "maturity": "Independent clocks now demonstrate the principle at extraordinary accuracy and support metrology, geodesy, and fundamental tests.",
        "uncertainties": [
          "The eventual redefinition and long-term societal deployment of time standards remain unfinished."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Kwang-Je Kim",
        "Claudio Pellegrini",
        "Jörg Rossbach"
      ],
      "assessment": {
        "nobel_worthiness": "The SASE X-ray free-electron laser opened access to ultrafast, coherent X-ray imaging and spectroscopy that conventional sources could not provide.",
        "attribution": "Kim's foundational SASE analysis and Pellegrini and Rossbach's leadership in turning the concept into a working X-ray source form a plausible original-credit group.",
        "maturity": "Multiple operating facilities have confirmed the method and made it an indispensable experimental instrument.",
        "uncertainties": [
          "Large-facility development involved many indispensable contributors, so the specific original contributions must be documented with unusual care."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Kenji Watanabe",
        "Takashi Taniguchi",
        "Philip Kim"
      ],
      "assessment": {
        "nobel_worthiness": "Ultrapure hexagonal boron nitride enabled clean van der Waals heterostructures and made many delicate two-dimensional quantum phenomena experimentally accessible.",
        "attribution": "Watanabe and Taniguchi's crystal-growth achievement is the indispensable original materials advance; Kim is a prominent early architect of the resulting heterostructure physics.",
        "maturity": "The material platform is widely reproduced and has become standard infrastructure for two-dimensional condensed-matter experiments.",
        "uncertainties": [
          "It is difficult to distinguish a Nobel-scale original discovery from a crucial enabling materials advance, and credit across the heterostructure field is broad."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B017",
      "proposed_laureates": [
        "John B. Pendry",
        "David R. Smith"
      ],
      "assessment": {
        "nobel_worthiness": "Negative-refraction metamaterials and transformation optics gave physicists new control over electromagnetic propagation through deliberately structured matter.",
        "attribution": "Pendry provided decisive theoretical formulations, and Smith supplied landmark experimental realization of negative-index metamaterials.",
        "maturity": "The underlying effects have been extensively reproduced and stimulated a durable field of engineered electromagnetic media.",
        "uncertainties": [
          "Some early spectacular applications were overstated, and the relation between negative refraction, metamaterials broadly, and transformation optics needs a sharply defined prize citation."
        ]
      }
    }
  ]
}
